// Comparar (#/comparar) — design V3Compare: one direct answer, sites A/B/C side by side, rules in sight.
// Values: LOLA + SPICE hourly series over the same window for every site (EST). Battery: N/D (not computed).
// Source of truth: this .tsx file (Preact). comparar.js is generated by `npm --prefix web run build:ts`.
import { h, Fragment } from "../../vendor/preact/preact.module.js";
import { num, setLevel } from "../../ds/components.js";
import { buildHash } from "../../ds/router.js";
import { LayerCard, mount } from "../../ds/ui.js";
import { compareLive } from "../live-compare.js";
import { windowMetrics } from "../data.js";
import { evaluate, rulesFromQuery, METRICS, bestIndex } from "../compare.js";
import { scenario, ContextBar, pickedSites, seriesFor, seriesProof, HourStrip, LETTERS, setQuery } from "./common.js";
const G = "est";
/** Shared loader for #/comparar and #/comparar/tecnico. */
export async function loadComparison(ctx) {
    const sc = await scenario(ctx);
    const sites = pickedSites(sc.data, ctx.query);
    const loaded = await seriesFor(sites);
    const entries = loaded.map(({ site, series, error }) => ({
        id: site.id, name: site.name, site, series,
        w: (series ? windowMetrics(series, sc.t0, sc.hours) : { status: "NOT_COMPUTED", reason: error }),
    }));
    const live = await compareLive(sites.map(s => s.id), sc.t0, sc.hours);
    if (live)
        for (const entry of entries)
            entry.w = live.get(entry.id);
    const rules = rulesFromQuery(ctx.query);
    return { sc, entries, rules, live: Boolean(live), result: evaluate(entries, rules) };
}
export const fmtMetric = (v, unit) => (unit === "%" ? num(v, 0, "%") : num(v, 0, " h"));
const short = (n) => n.replace(/\s*\(.*\)$/, "");
export function SitePickers({ ctx, sc, entries }) {
    return (h("div", { class: "row wrap", role: "group", "aria-label": "Locais comparados" }, LETTERS.slice(0, entries.length).map((L, i) => h("label", { class: "ctx glass" },
        h("span", { class: "wpill-letter" }, L),
        h("select", { "aria-label": "Local " + L, onChange: e => setQuery(ctx, { [L.toLowerCase()]: e.target.value }) }, sc.data.sites.map(s => h("option", { value: s.id, ...(s.id === entries[i].id ? { defaultSelected: true } : {}) }, short(s.name))))))));
}
export async function render(outlet, ctx) {
    const { sc, entries, rules, result, live } = await loadComparison(ctx);
    const { rows, best, closest } = result;
    const letterOf = (id) => LETTERS[rows.findIndex(r => r.id === id)];
    const answerText = best
        ? h(Fragment, null,
            h("span", { class: "big" }, letterOf(best.id) + " · " + short(best.name)),
            "atende \u00E0s tr\u00EAs regras e tem mais horas com Sol e Terra juntos.")
        : closest
            ? h(Fragment, null,
                h("span", { class: "big" }, "Nenhum atende a tudo"),
                "O mais próximo é " + letterOf(closest.id) + " · " + short(closest.name) + " (" + closest.fails + " regra(s) falham).")
            : h(Fragment, null,
                h("span", { class: "big" }, "N/D"),
                "N\u00E3o h\u00E1 s\u00E9rie calculada para esta janela.");
    const metricCards = METRICS.map(m => {
        const bi = bestIndex(rows, m);
        return h(LayerCard, { title: m.label, badge: "est", globalBadge: G, answer: h(Fragment, null,
                h("div", { class: "vals", style: { "--n": String(rows.length) } }, rows.map((r, i) => {
                    const v = r.computed ? r.w[m.key] : NaN;
                    const chk = r.checks.find(c => c.key === m.key);
                    const fail = chk && chk.pass === false;
                    return h("div", { class: "v" + (i === bi ? " best" : "") + (fail ? " fail" : "") },
                        h("span", null, LETTERS[i] + (i === bi ? " · melhor" : "") + (fail ? " · falha" : "")),
                        h("b", null, fmtMetric(v, m.unit)));
                })),
                m.rule ? h("span", { class: "rule" }, "Regra: " + m.text(rules) + " (premissa)") : h("span", { class: "rule" }, "Sem regra: s\u00F3 informativo")), why: m.key === "longestDarkH" ? "Noite longa exige bateria maior: é a sequência mais longa de horas sem Sol."
                : m.key === "longestBlackoutH" ? "Tempo seguido sem a Terra no céu: sem comunicação direta (geometria, não rádio)."
                    : m.key === "sunPct" ? "Fração das horas com o centro do Sol acima do relevo." : "Fração das horas da janela, mesma definição do Explorar.", proof: rows.map((r, i) => [LETTERS[i] + " · " + short(r.name), r.computed ? fmtMetric(r.w[m.key], m.unit) + (m.rule ? " · margem " + fmtMetric(r.checks.find(c => c.key === m.key).margin, m.unit) : "") : "N/D"]) });
    });
    mount(outlet, h(Fragment, null,
        h("div", { class: "page-head" },
            h("div", null,
                h("p", { class: "lbl-s" }, "Comparar locais de pouso"),
                h("h1", { "data-route-title": "" }, "Qual local atende \u00E0s regras nesta janela?")),
            h(ContextBar, { ctx: ctx, sc: sc, siteSelect: false })),
        h("p", { class: "t3 small", role: "status" }, live ? "API Go ao vivo · métricas preliminares" : "API indisponível para esta janela · métricas da série estática versionada"),
        h(SitePickers, { ctx: ctx, sc: sc, entries: entries }),
        h("div", { class: "split" },
            h("div", { class: "stack" },
                h(LayerCard, { title: "Resposta", badge: best || closest ? "est" : "nd", globalBadge: G, surface: "glass", answer: answerText, why: "S\u00F3 geometria: Sol, Terra e noite a partir do relevo LOLA e das efem\u00E9rides SPICE. As regras s\u00E3o premissas do prot\u00F3tipo, edit\u00E1veis na compara\u00E7\u00E3o t\u00E9cnica. Energia e bateria n\u00E3o entram (N/D).", proof: [["Regras", "Maior noite ≤ " + rules.maxNightH + " h · Maior perda da Terra ≤ " + rules.maxEarthLossH + " h · Sol visível ≥ " + rules.minSunPct + "%"],
                        ["Desempate", "mais horas com Sol e Terra juntos"], ["Origem das métricas", live ? "Go API · POST /api/compare" : "Série estática versionada"],
                        ...(live ? [["SHA da requisição", entries[0]?.w.request_sha256 || "N/D"]] : []), ...seriesProof(entries[0] && entries[0].series, sc)] }),
                h("div", { class: "scen" }, rows.map((r, i) => h("a", { class: "wpill" + (best && best.id === r.id ? " on" : ""), href: buildHash("/explorar", { site: r.id, t: ctx.query.t, d: ctx.query.d }) },
                    h("span", { class: "letter" }, LETTERS[i]),
                    h("span", null,
                        short(r.name),
                        h("small", null, !r.computed ? "N/D · série indisponível" : r.passAll ? "Atende às regras" : "Falha em " + r.fails + " regra(s)")),
                    h("span", { class: "v" }, r.computed ? (r.passAll ? "✓ Atende" : "✕ Falha") : "N/D")))),
                h("section", { class: "solid card" },
                    h("h2", { class: "h-card" }, "Sol hora a hora na janela \u00B7 s\u00E9rie est\u00E1tica"),
                    h("div", { class: "stripes" }, rows.map((r, i) => h("div", { class: "s" },
                        h("span", null, LETTERS[i]),
                        r.series ? h(HourStrip, { series: r.series, t0: sc.t0, hours: sc.hours, body: "sun" }) : h("span", { class: "t3" }, "N/D")))),
                    h("p", { class: "t3 small row" },
                        h("i", { class: "sw sw-sun", "aria-hidden": "true" }),
                        "Sol vis\u00EDvel",
                        h("i", { class: "sw sw-none", "aria-hidden": "true" }),
                        "Sol abaixo do relevo")),
                h("div", { class: "row wrap" },
                    h("a", { class: "btnA", href: buildHash("/comparar/tecnico", ctx.query) }, "Compara\u00E7\u00E3o t\u00E9cnica \u2192"),
                    h("button", { type: "button", class: "btnG", onClick: () => outlet.querySelectorAll(".l3").forEach(c => setLevel(c, 2)) }, "Abrir tudo em Prova"))),
            h("div", { class: "stack" },
                h("div", { class: "cards2" },
                    metricCards,
                    h(LayerCard, { title: "Folga da bateria", badge: "nd", globalBadge: G, answer: h(Fragment, null,
                            h("span", { class: "big" }, "N/D"),
                            "N\u00E3o calculada para locais reais."), why: "A bateria depende de painel, carga e reserva. Esse modelo s\u00F3 existe no painel de bordo, com dados sint\u00E9ticos (SIM), e n\u00E3o \u00E9 aplicado aqui.", proof: [["Status", "não calculado"], ["Por quê", "sem modelo de energia validado para séries reais"]] }))))));
}
